"""Kitchen Sink page: building an IDE. What an IDE written in VP6 is made
of: a property grid with its editors shown, lists with
pictures and editable names, a code box with a fold marker, pictures drawn
like icons, a toolbar and a status bar, and the questions an IDE asks."""

import os
import tempfile

from vp6 import *

CODE = '''class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Form1'
    # endregion

    def Form_Load(self):
        print("Hello")
'''


class pgIDE(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Building an IDE'
        self.Width = 640
        self.Height = 440
        self.imlTools = ImageList(self, Left=600, Top=40,
                                  ListImages=['images/back.png|back', 'images/forward.png|forward', 'images/sun.png|sun'])
        self.tbrIDE = Toolbar(self, Left=0, Top=0, Width=640, Height=30, Align=1,
                              ImageList='imlTools', TextAlignment=2,
                              Buttons=['Back|back|back|Go back', 'Forward|forward|forward|Go forward', '<>', 'Light|sun|sun|A button kept at the right end (the <> spacer before it)'])
        self.tabParts = TabStrip(self, Left=8, Top=34, Width=624, Height=31,
                                 Tabs=['Property grid|grid', 'Lists|lists', 'Code|code', 'Pictures|pictures', 'Questions|questions'],
                                 DocumentMode=True)
        self.picGrid = PictureBox(self, Left=8, Top=70, Width=624, Height=330, BorderStyle=0,
                                  BackStyle=0)
        self.grdProps = FlexGrid(self.picGrid, Left=0, Top=0, Width=300, Height=230, Rows=0,
                                 FixedRows=0, FixedCols=0, Editable=True, EditorsShown=True,
                                 ExtendLastCol=True, ButtonMenu='mnuColor', SelectionMode=1)
        self.grdColors = FlexGrid(self.picGrid, Left=310, Top=0, Width=314, Height=230, Rows=1,
                                  Cols=3, FixedCols=0, Editable=True, EditorsShown=True,
                                  ButtonStyle=1, ColorPicker=1, SelectionMode=3, StretchCol=0)
        self.lblDescription = Label(self.picGrid, Caption='', Left=0, Top=240, Width=624,
                                    Height=60, WordWrap=True, Selectable=True, BorderStyle=2,
                                    Margin=6)
        self.lblHint = Label(self.picGrid, Caption='Height:', Left=0, Top=304, Width=60, Height=25,
                             VerticalAlignment=1)
        self.spnZoom = SpinBox(self.picGrid, Left=64, Top=304, Width=90, Height=25, Max=72,
                               SpecialValueText='(Default)')
        self.picLists = PictureBox(self, Left=8, Top=70, Width=624, Height=330, BorderStyle=0,
                                   BackStyle=0, Visible=False)
        self.lvwFiles = ListView(self.picLists, Left=0, Top=0, Width=380, Height=160, View=3,
                                 ColumnHeaders=['Name|name|160', 'Size|size|60|right|contents', 'Where|where|100|left|fill'],
                                 LabelEdit=1, AlternatingRowColors=True, SmallIcons='imlFiles')
        self.lvwIcons = ListView(self.picLists, Left=390, Top=0, Width=234, Height=160,
                                 Icons='imlBig', GridWidth=110, GridHeight=72)
        self.tvwParts = TreeView(self.picLists, Left=0, Top=170, Width=380, Height=160,
                                 MultiSelect=True)
        self.lstRecent = ListBox(self.picLists, Left=390, Top=170, Width=234, Height=160)
        self.imlFiles = ImageList(self.picLists, Left=560, Top=300, ImageWidth=16, ImageHeight=16)
        self.imlBig = ImageList(self.picLists, Left=590, Top=300)
        self.picCode = PictureBox(self, Left=8, Top=70, Width=624, Height=330, BorderStyle=0,
                                  BackStyle=0, Visible=False)
        self.codDemo = CodeBox(self.picCode, Text='', Left=0, Top=0, Width=380, Height=200,
                               Language=1, ProtectedShading=1, FoldMarkerColor=0x808080,
                               SelBackColor=0xFFD6AD)
        self.rtbChat = RichTextBox(self.picCode, Text='', Left=390, Top=0, Width=234, Height=200,
                                   Locked=True, Margin=10)
        self.txtAsk = TextBox(self.picCode, Text='', Left=390, Top=206, Width=234, Height=25,
                              Placeholder='Ask something and press Enter', ContextMenu='mnuText')
        self.trmOut = Terminal(self.picCode, Left=0, Top=206, Width=380, Height=124,
                               ContextMenu='mnuText')
        self.picPictures = PictureBox(self, Left=8, Top=70, Width=624, Height=330, BorderStyle=0,
                                      BackStyle=0, Visible=False)
        self.picDraw = PictureBox(self.picPictures, Left=0, Top=0, Width=300, Height=200,
                                  AutoRedraw=True, BackColor=0xFFFFFF)
        self.tbnOpen = ToolButton(self.picPictures, Caption='Open a folder', Left=310, Top=0,
                                  Width=160, Height=30, ButtonStyle=2, AutoSize=True, IconSize=24,
                                  Alignment=0)
        self.chkEnabled = CheckBox(self.picPictures, Caption='Enabled (a faded picture while not)',
                                   Left=310, Top=40, Width=300, Height=25, Value=1)
        self.lblSystem = Label(self.picPictures,
                               Caption='Colored with the system colors vpInfoBackground and vpInfoText: they follow the light or dark look',
                               Left=310, Top=72, Width=300, Height=56, WordWrap=True,
                               BorderStyle=1, Margin=4, BackColor=vpInfoBackground,
                               ForeColor=vpInfoText)
        self.imgFile = Image(self.picPictures, Left=310, Top=130, Width=32, Height=32)
        self.lblFile = Label(self.picPictures, Caption='', Left=350, Top=130, Width=270, Height=32,
                             VerticalAlignment=1)
        self.picQuestions = PictureBox(self, Left=8, Top=70, Width=624, Height=330, BorderStyle=0,
                                       BackStyle=0, Visible=False)
        self.cmdNumber = CommandButton(self.picQuestions, Caption='Go to line…', Left=0, Top=0,
                                       Width=150, Height=30)
        self.cmdSave = CommandButton(self.picQuestions, Caption='Close (unsaved)…', Left=160,
                                     Top=0, Width=150, Height=30)
        self.cmdMade = CommandButton(self.picQuestions, Caption='Made it…', Left=320, Top=0,
                                     Width=150, Height=30)
        self.cmdTrash = CommandButton(self.picQuestions, Caption='Move a file to the Trash',
                                      Left=0, Top=40, Width=230, Height=30)
        self.cmdHelp = CommandButton(self.picQuestions, Caption='Search the help', Left=240,
                                     Top=40, Width=150, Height=30)
        self.lblAnswer = Label(self.picQuestions, Caption='', Left=0, Top=80, Width=620, Height=25)
        self.lblScreen = Label(self.picQuestions, Caption='', Left=0, Top=110, Width=620,
                               Height=200, WordWrap=True, Selectable=True)
        self.sbIDE = StatusBar(self, Left=0, Top=410, Width=640, Height=30, Align=2, Style=1,
                               AutoSize=True, SizeGrip=True)
        self.dlgColor = CommonDialog(self, Left=560, Top=40)
        self.mnuColor = Menu(self, Caption='Color', Visible=False)
        self.mnuColorDefault = Menu(self.mnuColor, Caption='(Default)')
        self.mnuColorChoose = Menu(self.mnuColor, Caption='Choose…',
                               Description='Pick any color in the system’s color dialog',
                               MenuRole=1)
        self.mnuColorWeb = Menu(self.mnuColor, Caption='Web colors only', Checkable=True)
        self.mnuText = Menu(self, Caption='Text', Visible=False)
        self.mnuTextCopy = Menu(self.mnuText, Caption='&Copy', Shortcut='{Copy}')
        self.mnuTextClear = Menu(self.mnuText, Caption='C&lear')
    # endregion

    def Form_Load(self):
        self.fill_grid()
        self.fill_lists()
        self.fill_code()
        self.draw()
        self.show_screen()

    def tabParts_Click(self):
        key = self.tabParts.SelectedItem.Key
        for name in ("grid", "lists", "code", "pictures", "questions"):
            getattr(self, "pic" + name.capitalize()).Visible = name == key
        self.sbIDE.ShowMessage(f"The {self.tabParts.SelectedItem.Caption} page", 3000)

    def tbrIDE_ButtonClick(self, Button):
        self.sbIDE.ShowMessage(f"{Button.Key} clicked (a message for 2 seconds)", 2000)

    # -- the property grid ----------------------------------------------------------------------
    def fill_grid(self):
        grid = self.grdProps
        grid.Cols = 2
        rows = [("Caption", "Form1", vpGridEditText, None),
                ("BorderStyle", "2 - Sizable", vpGridEditList,
                 ["0 - None", "1 - Fixed Single", "2 - Sizable"]),
                ("ForeColor", "#000080", vpGridEditColor, None),
                ("Picture", "", vpGridEditTextButton, None),
                ("DataField", "", vpGridEditCombo, ["Name", "Price"]),
                ("Visible", "True", vpGridEditCheck, None)]
        grid.Rows = len(rows)
        grid.RowHeight[-1] = 22  # (every row)
        grid.ColWidth[0] = 100
        grid.ColEditor[0] = vpGridEditNone
        for row, (name, value, editor, choices) in enumerate(rows):
            grid.TextMatrix[row, 0] = name
            grid.Row, grid.Col = row, 1
            grid.CellEditor = editor
            if choices:
                grid.CellList = choices
            if name == "Picture":
                grid.CellPlaceholder = "(None)"
            grid.TextMatrix[row, 1] = value
        grid.Row = -1  # (no row chosen yet)
        colors = self.grdColors
        colors.RowHeight[-1] = 30
        for col, title in enumerate(("Element", "Color", "Bold")):
            colors.TextMatrix[0, col] = title
        colors.ColEditor[0] = vpGridEditNone
        colors.ColEditor[1] = vpGridEditColor
        colors.ColEditor[2] = vpGridEditCheck  # (a check box in the middle of the cell)
        colors.ColWidth[1], colors.ColWidth[2] = 95, 40
        elements = [("Keywords", "#0000ff", "True"), ("Strings", "#a31515", "False"),
                    ("Comments", "#008000", "False")]
        colors.Rows = len(elements) + 1
        for row, (name, color, bold) in enumerate(elements, 1):
            colors.TextMatrix[row, 0] = name
            colors.TextMatrix[row, 1] = color
            colors.TextMatrix[row, 2] = bold

    def grdProps_RowColChange(self):
        name = self.grdProps.TextMatrix(self.grdProps.Row, 0) if self.grdProps.Row >= 0 else ""
        self.lblDescription.Caption = f"{name}: EditorsShown shows every cell's editor, as " \
            "a Properties window does (a list's box, a field, a color's button with " \
            "ButtonMenu's menu, a check box). Select this text with the mouse: Selectable."

    def mnuColorDefault_Click(self):
        self.grdProps.TextMatrix[self.grdProps.Row, 1] = ""

    def mnuColorChoose_Click(self):
        self.dlgColor.DialogTitle = "ForeColor"
        if self.dlgColor.ShowColor():
            color = self.dlgColor.Color
            self.grdProps.TextMatrix[self.grdProps.Row, 1] = \
                f"#{color & 0xFF:02x}{(color >> 8) & 0xFF:02x}{(color >> 16) & 0xFF:02x}"

    def mnuColorWeb_Click(self):
        self.sbIDE.ShowMessage(f"Web colors only: {self.mnuColorWeb.Checked}", 2000)

    def grdColors_CellButtonClick(self, Row, Col):
        """ColorPicker = CellButtonClick: a picker of the program's own."""
        self.dlgColor.DialogTitle = self.grdColors.TextMatrix(Row, 0)
        if self.dlgColor.ShowColor():
            color = self.dlgColor.Color
            self.grdColors.TextMatrix[Row, Col] = \
                f"#{color & 0xFF:02x}{(color >> 8) & 0xFF:02x}{(color >> 16) & 0xFF:02x}"

    def spnZoom_Change(self):
        size = int(self.spnZoom.Value)
        self.grdProps.RowHeight[-1] = 22 if size == 0 else size  # ((Default) at 0)

    # -- lists ------------------------------------------------------------------------------------
    def fill_lists(self):
        folder = os.path.dirname(os.path.abspath(__file__))
        self.imlFiles.ListImages.Add(Key="file", Picture=FileIcon(__file__, 16))
        self.imlFiles.ListImages.Add(Key="folder", Picture=FileIcon(folder, 16))
        items = self.lvwFiles.ListItems
        for name, size, where in (("Form1.py", "12 KB", "the project"),
                                  ("pgIDE.py", "9 KB", "the project"),
                                  ("images", "", "a folder")):
            item = items.Add(Key=name, Text=name, SmallIcon="folder" if not size else "file")
            item.SubItems[1], item.SubItems[2] = size, where
        items("pgIDE.py").Bold = True  # (the one shown)
        items("images").SetSubItemColor(2, 0x808080)  # (a dimmed column)
        big = self.imlBig.ListImages
        big.Add(Key="file", Picture=FileIcon(__file__, 32))
        for name in ("Standard EXE", "Console Application", "Kitchen Sink"):
            self.lvwIcons.ListItems.Add(Key=name, Text=name, Icon="file")
        nodes = self.tvwParts.Nodes
        nodes.Add(None, None, "forms", "Forms")
        for name in ("Form1", "pgIDE"):
            node = nodes.Add("forms", vpTvwChild, name, name)
            node.ToolTipText = f"{name}.py, in the project's folder"
        nodes("forms").Expanded = True
        for index, path in enumerate(("Demo.vp6p", "Notes.vp6p")):
            self.lstRecent.AddItem(path)
            self.lstRecent.ItemToolTip[index] = os.path.join(tempfile.gettempdir(), path)

    def lvwFiles_DblClick(self):
        if self.lvwFiles.SelectedItem is not None:
            self.lvwFiles.StartLabelEdit()  # (LabelEdit Manual: renamed only this way)

    def lvwFiles_AfterLabelEdit(self, Item, NewString):
        if not NewString.endswith(".py") and Item.Key != "images":
            self.sbIDE.ShowMessage("A module's name ends with .py", 3000)
            return True  # (refused)
        self.sbIDE.ShowMessage(f"Renamed to {NewString}", 3000)
        return False

    def tvwParts_NodeClick(self, Node):
        names = ", ".join(node.Text for node in self.tvwParts.SelectedNodes)
        self.sbIDE.ShowMessage(f"Selected: {names}", 3000)

    # -- code ---------------------------------------------------------------------------------------
    def fill_code(self):
        box = self.codDemo
        box.Text = CODE
        box.ProtectLines(1, 4)  # (the designer region: shaded as far as its text goes)
        box.SetFoldMarker(1, False)
        self.folded = False
        self.rtbChat.AppendHTML("<b>Claude</b>: Ask me anything, or "
                                "<a href='https://example.com'>read the guide</a>.")
        self.trmOut.Display("A Terminal shows text with Display, without a program.\r\n")

    def codDemo_GutterClick(self, Line):
        if Line != 1:
            return
        self.folded = not self.folded
        self.codDemo.ShowLines()
        if self.folded:
            self.codDemo.HideLines(2, 4)
        self.codDemo.SetFoldMarker(1, self.folded)  # (+ while folded, - while not)

    def rtbChat_LinkClick(self, URL):
        self.sbIDE.ShowMessage(f"LinkClick: {URL}", 3000)

    def txtAsk_KeyPress(self, KeyAscii):
        if KeyAscii == 13 and self.txtAsk.Text.strip():
            self.rtbChat.AppendHTML(f"<p><b>You</b>: {self.txtAsk.Text}</p>")
            self.txtAsk.Text = ""
            return 0
        return KeyAscii

    def mnuTextCopy_Click(self):
        self.sbIDE.ShowMessage("Copy (the menu's Shortcut is the system's own Copy key)", 3000)

    def mnuTextClear_Click(self):
        self.txtAsk.Text = ""

    def trmOut_KeyDown(self, KeyCode, Shift):
        if KeyCode == vpKeyReturn:  # (no program runs: its keys are the program's own)
            self.trmOut.Display("Enter pressed\r\n")

    # -- pictures ---------------------------------------------------------------------------------
    def draw(self):
        pic = self.picDraw
        pic.DrawWidth = 8
        pic.DrawCap, pic.DrawJoin = vpCapRound, vpJoinRound
        pic.Line(20, 30, 120, 30, 0x2B2B2B)
        pic.DrawCap, pic.DrawJoin = vpCapSquare, vpJoinBevel
        pic.Polygon([(20, 60), (120, 60), (70, 120)], 0x2B2B2B)
        pic.DrawWidth = 1
        disc = GraphicsPath().AddEllipse(160, 30, 100, 100)
        bite = GraphicsPath().AddEllipse(200, 10, 80, 80)
        pic.DrawPath(disc.Subtract(bite), 0x993333, 0xFFC0C0)  # (a moon)
        both = GraphicsPath().AddRect(160, 140, 60, 40, Radius=8).Unite(
            GraphicsPath().AddPolygon([(170, 175), (165, 195), (190, 178)]))
        pic.DrawPath(both, 0x2B2B2B, 0xFFFFFF)  # (a speech bubble, one outline)
        pic.DrawPath(GraphicsPath().AddRect(230, 140, 50, 40).Intersect(
            GraphicsPath().AddEllipse(240, 130, 60, 60)), 0x2B2B2B, 0xC0E0FF)
        pic.FontSize = 9
        pic.FontScale = 2  # (the letters magnified, as a scaled drawing shows them)
        pic.CurrentX, pic.CurrentY = 20, 140
        pic.Print("Aa")
        icon = FileIcon(os.path.dirname(os.path.abspath(__file__)), 24)
        icon.DisabledPicture = icon.Faded(0.35)  # (shown while the button is disabled)
        self.tbnOpen.Picture = icon
        self.imgFile.Picture = FileIcon(__file__, 32)
        self.lblFile.Caption = "FileIcon: the system's icon for this file"

    def chkEnabled_Click(self):
        self.tbnOpen.Enabled = self.chkEnabled.Value == vpChecked

    def tbnOpen_DblClick(self):
        self.sbIDE.ShowMessage("DblClick on a ToolButton", 3000)

    # -- questions ----------------------------------------------------------------------------------
    def cmdNumber_Click(self):
        line = InputNumber("Line number (1 - 100):", "Go to Line", 1, 1, 100)
        self.lblAnswer.Caption = "Cancelled" if line is None else f"Line {line}"

    def cmdSave_Click(self):
        answer = MsgBox("Save changes to Form1.py?", vpSaveDiscardCancel + vpQuestion, "Close")
        self.lblAnswer.Caption = {vpSave: "Save", vpDiscard: "Discard"}.get(answer, "Cancel")

    def cmdMade_Click(self):
        answer = MsgBox("Made dist/Demo.app", vpOKOnly + vpInformation, "Make",
                        ExtraButton="Show in Folder")
        self.lblAnswer.Caption = "Show in Folder" if answer == vpExtraButton else "OK"

    def cmdTrash_Click(self):
        handle, path = tempfile.mkstemp(suffix=".txt", prefix="vp6-trash-")
        os.close(handle)
        moved = MoveToTrash(path)
        self.lblAnswer.Caption = f"{os.path.basename(path)} moved to the Trash" if moved \
            else "This system has no Trash"
        if not moved and os.path.exists(path):
            os.remove(path)

    def cmdHelp_Click(self):
        try:
            ShowHelp(Tab="Search")  # (its Search tab, the focus in its box)
        except FileNotFoundError:
            self.lblAnswer.Caption = "VP6's help isn't installed"

    def show_screen(self):
        types = ", ".join(ControlTypes(AsRegistered=True)[:6])
        self.lblScreen.Caption = (
            f"Screen.FontName {Screen.FontName}, FontSize {Screen.FontSize} points at "
            f"FontDPI {Screen.FontDPI:g}; LayoutSpacingX {Screen.LayoutSpacingX}, "
            f"LayoutSpacingY {Screen.LayoutSpacingY} pixels.\n"
            f"A button's PreferredWidth x PreferredHeight: {self.cmdSave.PreferredWidth} x "
            f"{self.cmdSave.PreferredHeight}.\n"
            f"This form: WindowWidth {self.WindowWidth}, WindowHeight {self.WindowHeight} (its "
            f"frame too), MenuBarHeight {self.MenuBarHeight}, DockTabPosition "
            f"{self.DockTabPosition}.\n"
            f"The Toolbox's first tools (ControlTypes(AsRegistered=True)): {types}…")
